const fs = require('fs');
const https = require('https');

const token = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const content = fs.readFileSync('backend/api/ivx-developer-deploy-control.ts');
const base64 = content.toString('base64');
console.log('file size:', content.length, 'base64 size:', base64.length);

const payload = JSON.stringify({
  action: 'github_commit_file',
  confirm: true,
  confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  input: {
    path: 'backend/api/ivx-developer-deploy-control.ts',
    content: base64,
    contentEncoding: 'base64',
    message: 'feat(deploy): add render_get_deploy_status action for exact Render deploy status'
  }
});

const options = {
  hostname: 'api.ivxholding.com',
  port: 443,
  path: '/api/ivx/developer-deploy/action',
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + token,
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

const req = https.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    console.log('status:', res.statusCode);
    try {
      const r = JSON.parse(data);
      console.log('commitSha:', r.commitSha || r.result?.commitSha || r.result?.commit?.sha || null);
      console.log('error:', r.error || null);
      if (r.error) console.log('full:', data.slice(0, 2000));
    } catch (e) {
      console.log('parse error:', data.slice(0, 500));
    }
  });
});

req.on('error', (e) => console.error('request error:', e.message));
req.write(payload);
req.end();
"

